<?php

declare(strict_types=1); session_start(); require_once __DIR__.'/../includes/cliente-auth.php';
$pend=$_SESSION['cliente_cadastro_pendente']??null; if(!is_array($pend)){http_response_code(400);exit('Não há cadastro de cliente pendente.');}
$pdo=getDB(); $empresa=clienteEmpresaPorSlug($pdo,(string)($pend['empresa_slug']??'')); if(!$empresa||(int)$empresa['id']!==(int)($pend['empresa_id']??0)){unset($_SESSION['cliente_cadastro_pendente']);http_response_code(404);exit('Empresa não encontrada.');}
$erro=null;$v=['nome_completo'=>trim((string)($pend['nome']??'')),'cpf'=>'','data_nascimento'=>'','genero'=>'nao_informado','celular'=>'','cep'=>'','logradouro'=>'','numero'=>'','complemento'=>'','bairro'=>'','cidade'=>'','estado'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){
 foreach(array_keys($v) as $k)$v[$k]=trim((string)($_POST[$k]??$v[$k]));$gen=['masculino','feminino','nao_binario','nao_informado'];
 if($v['nome_completo']==='')$erro='Informe seu nome completo.';elseif(strlen(clienteSomenteDigitos($v['cpf']))!==11)$erro='Informe um CPF válido.';elseif(!clienteDataValida($v['data_nascimento']))$erro='Informe sua data de nascimento.';elseif(!in_array($v['genero'],$gen,true))$erro='Gênero inválido.';elseif(strlen(clienteSomenteDigitos($v['celular']))<10||strlen(clienteSomenteDigitos($v['celular']))>11)$erro='Informe um celular/WhatsApp válido.';
 else try{$pdo->beginTransaction();$uid=(int)($pend['usuario_id']??0);$email=mb_strtolower((string)$pend['email']);$gid=$pend['google_id']??null;$foto=$pend['foto_url']??null;if($uid<=0){$stmt=$pdo->prepare('SELECT id,ativo,google_id FROM usuarios WHERE email=:email LIMIT 1 FOR UPDATE');$stmt->execute([':email'=>$email]);$u=$stmt->fetch(PDO::FETCH_ASSOC);if($u){if((int)$u['ativo']!==1)throw new RuntimeException('Conta desativada.');if(!empty($u['google_id'])&&(string)$u['google_id']!==(string)$gid)throw new RuntimeException('Este e-mail já está vinculado a outra conta Google.');$uid=(int)$u['id'];$stmt=$pdo->prepare('UPDATE usuarios SET google_id=COALESCE(google_id,:gid),foto_url=COALESCE(:foto,foto_url) WHERE id=:id');$stmt->execute([':gid'=>$gid,':foto'=>$foto?:null,':id'=>$uid]);}else{$stmt=$pdo->prepare('INSERT INTO usuarios (email,senha_hash,google_id,foto_url,ativo) VALUES (:email,NULL,:gid,:foto,1)');$stmt->execute([':email'=>$email,':gid'=>$gid,':foto'=>$foto?:null]);$uid=(int)$pdo->lastInsertId();}}
 $cliente=clienteSalvarPerfil($pdo,$empresa,$uid,$email,['nome_completo'=>$v['nome_completo'],'cpf'=>$v['cpf'],'data_nascimento'=>$v['data_nascimento'],'genero'=>$v['genero'],'celular'=>$v['celular'],'cep'=>$v['cep'],'logradouro'=>$v['logradouro'],'numero'=>$v['numero'],'complemento'=>$v['complemento'],'bairro'=>$v['bairro'],'cidade'=>$v['cidade'],'estado'=>mb_strtoupper($v['estado'])]);$pdo->commit();clienteIniciarSessao($pdo,['id'=>$uid,'email'=>$email],$cliente,$empresa);header('Location: dashboard-cliente.php');exit;}catch(RuntimeException $e){if($pdo->inTransaction())$pdo->rollBack();$erro=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Erro completar cliente: '.$e->getMessage());$erro='Não foi possível concluir seu cadastro agora.';}
}
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,shrink-to-fit=no"><title>Complete seu cadastro</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@4.6.2/dist/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/cliente-cadastro.css"></head><body><div class="cliente-cadastro-page"><div class="container"><div class="cliente-cadastro-card"><div class="mb-4"><div class="cliente-cadastro-brand"><?=htmlspecialchars((string)$empresa['nome_fantasia'],ENT_QUOTES,'UTF-8')?></div><h1 class="h3 mt-2">Complete seu cadastro</h1><p class="text-muted">E-mail: <strong><?=htmlspecialchars((string)$pend['email'],ENT_QUOTES,'UTF-8')?></strong></p></div><?php if($erro):?><div class="alert alert-danger"><?=htmlspecialchars($erro,ENT_QUOTES,'UTF-8')?></div><?php endif;?><form id="cadastroClienteForm" method="post" novalidate><div class="form-row"><div class="form-group col-md-8"><label>Nome completo</label><input class="form-control" name="nome_completo" value="<?=htmlspecialchars($v['nome_completo'],ENT_QUOTES,'UTF-8')?>" required></div><div class="form-group col-md-4"><label>CPF</label><input class="form-control" name="cpf" id="cpf" maxlength="14" required></div></div><div class="form-row"><div class="form-group col-md-6"><label>Data de nascimento</label><input type="date" class="form-control" name="data_nascimento" required></div><div class="form-group col-md-6"><label>Gênero</label><select class="form-control" name="genero"><option value="nao_informado">Prefiro não informar</option><option value="feminino">Feminino</option><option value="masculino">Masculino</option><option value="nao_binario">Não binário</option></select></div></div><div class="form-group"><label>Celular / WhatsApp</label><input class="form-control" name="celular" id="celular" maxlength="15" required></div><h2 class="h5 mt-4">Endereço</h2><div class="form-row"><div class="form-group col-md-3"><label>CEP</label><input class="form-control" name="cep" id="cep" maxlength="9" placeholder="00000-000" inputmode="numeric" autocomplete="postal-code"><small id="cepFeedback" class="form-text" aria-live="polite"></small></div><div class="form-group col-md-7"><label>Logradouro</label><input class="form-control" name="logradouro" id="logradouro" autocomplete="address-line1"></div><div class="form-group col-md-2"><label>Número</label><input class="form-control" name="numero" id="numero"></div></div><div class="form-row"><div class="form-group col-md-4"><label>Complemento</label><input class="form-control" name="complemento" id="complemento" autocomplete="address-line2"></div><div class="form-group col-md-4"><label>Bairro</label><input class="form-control" name="bairro" id="bairro"></div><div class="form-group col-md-3"><label>Cidade</label><input class="form-control" name="cidade" id="cidade" autocomplete="address-level2" readonly></div><div class="form-group col-md-1"><label>UF</label><input class="form-control" name="estado" id="estado" maxlength="2" autocomplete="address-level1" readonly></div></div><button class="btn btn-primary btn-lg btn-block">Concluir cadastro</button></form></div></div></div><script src="assets/js/consulta-cep.js"></script><script src="assets/js/cadastro-cliente.js"></script></body></html>
